script:
import * as THREE from "three";
import { animate } from "animejs";
import { createElement as h } from "react";
import { createRoot } from "react-dom/client";
import { ReactFlow } from "@xyflow/react";

document.body.style.cssText = "display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;height:100%;font:13px system-ui";

// three.js: a spinning cube.
const cube = document.createElement("div");
document.body.append(cube);
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(320, 160);
cube.append(renderer.domElement);
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(50, 2, 0.1, 10);
camera.position.z = 3;
const mesh = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshNormalMaterial());
scene.add(mesh);
renderer.setAnimationLoop((t) => {
  mesh.rotation.set(t / 1000, t / 1400, 0);
  renderer.render(scene, camera);
});

// anime.js: a dot sliding back and forth.
const lane = document.createElement("div");
lane.style.cssText = "position:relative;padding:16px";
lane.innerHTML = '<div>anime.js</div><div class="dot" style="position:absolute;top:60px;left:16px;width:16px;height:16px;border-radius:50%;background:#4f5bd5"></div>';
document.body.append(lane);
animate(".dot", { translateX: 240, duration: 1200, alternate: true, loop: true, ease: "inOutQuad" });

// React Flow: two connected nodes.
const flow = document.createElement("div");
flow.style.cssText = "grid-column:1 / span 2";
document.body.append(flow);
createRoot(flow).render(
  h(ReactFlow, {
    defaultNodes: [
      { id: "a", position: { x: 40, y: 20 }, data: { label: "three.js r" + THREE.REVISION } },
      { id: "b", position: { x: 320, y: 60 }, data: { label: "React Flow" } },
    ],
    defaultEdges: [{ id: "a-b", source: "a", target: "b", animated: true }],
    // The flow fills its cell; nodes and the view stay inside it.
    nodeExtent: [[0, 0], [flow.clientWidth, flow.clientHeight]],
    translateExtent: [[0, 0], [flow.clientWidth, flow.clientHeight]],
    minZoom: 1,
    maxZoom: 1,
    proOptions: { hideAttribution: true },
  }),
);
